css_rules.declarations:
position: static !important;
    width: 100%;
    min-height: 80px;
    display: grid;
    grid-template-areas: 'left center right';
    grid-gap: var(--gap-xl);
    --header-left: 1fr;
    --header-center: auto;
    --header-right: 1fr;
    grid-template-columns: var(--header-left) var(--header-center) var(--header-right);
    align-items: center;
